/* From Uiverse.io by AbanoubMagdy1 - Tags: switch, flip */
.__UIV_SCOPE__ .switch {
  --circle-dim: 1.4em;
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #f5aeae;
  transition: .4s;
  border-radius: 30px;
}

.__UIV_SCOPE__ .slider-card {
  position: absolute;
  content: "";
  height: var(--circle-dim);
  width: var(--circle-dim);
  border-radius: 20px;
  left: 0.3em;
  bottom: 0.3em;
  transition: .4s;
  pointer-events: none;
}

.__UIV_SCOPE__ .slider-card-face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  perspective: 1000px;
  border-radius: 50%;
  transition: .4s transform;
}

.__UIV_SCOPE__ .slider-card-front {
  background-color: #DC3535;
}

.__UIV_SCOPE__ .slider-card-back {
  background-color: #379237;
  transform: rotateY(180deg);
}

.__UIV_SCOPE__ input:checked ~ .slider-card .slider-card-back {
  transform: rotateY(0);
}

.__UIV_SCOPE__ input:checked ~ .slider-card .slider-card-front {
  transform: rotateY(-180deg);
}

.__UIV_SCOPE__ input:checked ~ .slider-card {
  transform: translateX(1.5em);
}

.__UIV_SCOPE__ input:checked ~ .slider {
  background-color: #9ed99c;
}
